**TABLE_VIEW** **SELECT** <人物>
{
  {
    **SELECT** name, wolf
    **FROM** "示例/域示例/人物"
    **WHERE** type %==% '人物'
  } **AS** <人物>
}

**TABLE_VIEW** **SELECT** <人物>, <武器>
{
  {
    **SELECT** name, wolf
    **FROM** "示例/域示例/人物"
  } **AS** <人物>

  {
    **SELECT** name
    **FROM** "示例/域示例/武器"
  } **AS** <武器>
}

**TABLE_VIEW** **SELECT** <人物>, <武器>, $人物有武器$
{
  {
    **SELECT** name, wolf
    **FROM** "示例/域示例/人物"
    **WHERE** type %==% '人物'
  } **AS** <人物>

  {
    **SELECT** name
    **FROM** "示例/域示例/武器"
    **WHERE** type %==% '武器'
  } **AS** <武器>

  **YIELD**
    <武器>::name **IN** <人物>::wolf **AS** $人物有武器$
}

**TABLE_VIEW** **SELECT** <人物>, $未引用$
{
  {
    **SELECT** name
    **FROM** "示例/域示例/武器"
    **WHERE** type %==% '武器'
  } **AS** <武器>

  {
    **SELECT** name, wolf
    **FROM** "示例/域示例/人物"
    **WHERE** type %==% '人物'
  } **AS** <人物>

  **YIELD**
    <武器>::name **DIFF** <人物>::wolf **AS** $未引用$
}

**TABLE_VIEW** **SELECT** <剧情>, <人物>, $在剧情里$, $非剧情人物$
{
  {
    **SELECT** name, chart
    **FROM** "示例/域示例/剧情"
    **WHERE** name %==% '苍蓝传'
  } **AS** <剧情>

  {
    **SELECT** name
    **FROM** "示例/域示例/人物"
    **WHERE** type %==% '人物'
  } **AS** <人物>

  **YIELD**
    <人物>::name **IN** <剧情>::chart      **AS** $在剧情里$,
    <剧情>::chart **DIFF** <人物>::name    **AS** $非剧情人物$
}

**TABLE_VIEW** **SELECT** <人物>, <武器>, $人物有武器$
{
  {
    **SELECT** name, wolf
    **FROM** "示例/域示例/人物"
    **WHERE** type %==% '人物'

    {
      **SELECT** name
      **FROM** "示例/域示例/内层"
      **WHERE** type %==% '武器'
    } **AS** <武器>
  } **AS** <人物>

  {
    **SELECT** name
    **FROM** "示例/域示例/武器"
    **WHERE** type %==% '武器'
  } **AS** <武器>

  **YIELD**
    <武器>::name **IN** <人物>::wolf **AS** $人物有武器$
}

**LIST_VIEW** **SELECT** <剧情>, <人物>, <武器>,
       $人物武器绑定$, $剧情人物$, $未引用$
{
  {
    **SELECT** name, chart
    **FROM** "示例/域示例/剧情"
    **WHERE** name %==% '苍蓝传'
  } **AS** <剧情>

  {
    **SELECT** name, wolf
    **FROM** "示例/域示例/人物"
    **WHERE** type %==% '人物'
  } **AS** <人物>

  {
    **SELECT** name
    **FROM** "示例/域示例/武器"
    **WHERE** type %==% '武器'
  } **AS** <武器>

  **YIELD**
    <武器>::name **IN** <人物>::wolf       **AS** $人物武器绑定$,
    <人物>::name **IN** <剧情>::chart      **AS** $剧情人物$,
    <武器>::name **DIFF** <人物>::wolf     **AS** $未引用$
}
